14	const storeFileName = "shadow-store.json"
15	const storeFormat = 1
16	
17	// View 是设备影子当前状态的只读快照。
18	type View struct {
19		DeviceID string
20		// Version 是设备当前版本（登记时的初始版本，随有效上报更新）。
21		Version string
22		// Online 表示设备是否在线。新登记设备离线，有效上报置为在线。
23		Online bool
24		// Revision 是当前期望配置的修订号，从零开始，每次成功修改加一。
25		Revision uint64
26		// Desired 是期望配置的完整 JSON 对象。
27		Desired json.RawMessage
28		// Reported 是上报配置的完整 JSON 对象。
29		Reported json.RawMessage
30		// LastSeq 是最后接受的上报序号。
31		LastSeq uint64
32	}
33	
34	// AuditRecord 是一次成功修改期望配置的审计记录。
35	type AuditRecord struct {
36		DeviceID string
37		Operator string
38		Time     time.Time
39		// Revision 是本次修改产生的新修订号。
40		Revision uint64
41		// RequestID 是产生本次修改的批量请求标识；单设备修改为空。
42		RequestID string
43		// Before 是修改前的完整期望配置。
44		Before json.RawMessage
45		// After 是修改后的完整期望配置。
46		After json.RawMessage
47	}
48	
49	// deviceState 是单台设备的内部状态。
50	type deviceState struct {
51		Version        string
52		Online         bool
53		Revision       uint64
54		Desired        json.RawMessage
55		Reported       json.RawMessage
56		LastSeq        uint64
57		LastReportTime time.Time
58		// DiffSince 记录每条差异路径首次出现的时间。
59		DiffSince map[string]time.Time
60		Audit     []AuditRecord
61	}
62	
63	// validateLastReport 校验设备记录的最近上报侧必须自洽，只能表示以下两种
64	// 形态之一：
65	//   - 已经登记但从未上报：LastSeq 为 0，此时上报时间必须为零值、上报配置
66	//     必须是空 JSON 对象（按 JSON 内容判断，允许合法空白）、设备必须离线；
67	//     期望侧可以已经修改过（期望配置非空、存在审计或配置差异都合法）。
68	//   - 已有一次有效上报：LastSeq 为正整数，此时必须保存非零的上报时间；
69	//     上报配置允许是空对象，设备也允许随后被标记为离线。
70	//
71	// 两种形态的当前版本都必须非空。序号允许跳号。校验只检查记录自身的一致性，
72	// 不补时间、不改序号、不清空上报配置、不替换版本。
73	func (d *deviceState) validateLastReport() error {
74		if d.Version == "" {
75			return errors.New("version is empty")
76		}
77		if d.LastSeq == 0 {
78			if !d.LastReportTime.IsZero() {
79				return errors.New("never-reported device has a last report time")
80			}
81			reported, ok := decodeObject(d.Reported)
82			if !ok {
83				// 理论上 restore 已用 decodeObject 校验过，这里防御性处理。
84				return errors.New("never-reported device reported config invalid")
85			}
86			if len(reported) != 0 {
87				return errors.New("never-reported device has non-empty reported config")
88			}
89			if d.Online {
90				return errors.New("never-reported device is online")
91			}
92			return nil
93		}
94		if d.LastReportTime.IsZero() {
95			return errors.New("reported device has zero last report time")
96		}
97		return nil
98	}
99	
100	// refreshDiff 重新计算差异路径：已有路径保留原时间，新路径使用 t，消失的路径移除。
101	func (d *deviceState) refreshDiff(t time.Time) {
102		entries := computeDiff(d.Desired, d.Reported)
103		next := make(map[string]time.Time, len(entries))
104		for _, e := range entries {
105			if since, ok := d.DiffSince[e.Path]; ok {
106				next[e.Path] = since
107			} else {
108				next[e.Path] = t
109			}
110		}
111		d.DiffSince = next
112	}
