114	// Store 是本地设备影子存储，所有状态与审计记录保存在指定目录。
115	// Store 可安全并发使用。
116	type Store struct {
117		mu        sync.Mutex
118		dir       string
119		closed    bool
120		devices   map[string]*deviceState
121		versions  map[string]*versionState
122		campaigns map[string]*campaignState
123		batches   map[string]*batchRequestState
124	}
125	
126	// Open 打开（必要时创建）位于 dir 的本地影子存储。
127	// 已有内容损坏或格式不识别时返回 ErrCorruptStorage，不会按空数据覆盖。
128	func Open(dir string) (*Store, error) {
129		if err := os.MkdirAll(dir, 0o755); err != nil {
130			return nil, fmt.Errorf("shadow: create store dir: %w", err)
131		}
132		s := &Store{
133			dir:       dir,
134			devices:   map[string]*deviceState{},
135			versions:  map[string]*versionState{},
136			campaigns: map[string]*campaignState{},
137			batches:   map[string]*batchRequestState{},
138		}
139		data, err := os.ReadFile(s.filePath())
140		if errors.Is(err, fs.ErrNotExist) {
141			return s, nil
142		}
143		if err != nil {
144			return nil, fmt.Errorf("shadow: read store: %w", err)
145		}
146		if err := s.restore(data); err != nil {
147			return nil, err
148		}
149		return s, nil
150	}
151	
152	// Close 关闭存储。关闭后的操作返回 ErrClosed。
153	func (s *Store) Close() error {
154		s.mu.Lock()
155		defer s.mu.Unlock()
156		if s.closed {
157			return ErrClosed
158		}
159		s.closed = true
160		return nil
161	}
162	
163	// Register 登记一台模拟设备。设备标识和初始版本不能为空；
164	// 重复登记返回 ErrDeviceExists。新设备初始离线，双方配置均为空对象。
165	func (s *Store) Register(deviceID, version string) error {
166		s.mu.Lock()
167		defer s.mu.Unlock()
168		if err := s.checkOpen(); err != nil {
169			return err
170		}
171		if deviceID == "" {
172			return ErrInvalidDeviceID
173		}
174		if version == "" {
175			return ErrInvalidVersion
176		}
177		if _, ok := s.devices[deviceID]; ok {
178			return fmt.Errorf("%w: %s", ErrDeviceExists, deviceID)
179		}
180		return s.commit(func() error {
181			s.devices[deviceID] = &deviceState{
182				Version:   version,
183				Desired:   json.RawMessage(`{}`),
184				Reported:  json.RawMessage(`{}`),
185				DiffSince: map[string]time.Time{},
186			}
187			return nil
188		})
189	}
190	
191	// UpdateDesired 修改设备的期望配置，完整替换旧配置。
192	// 需携带操作者、操作时间和已读取的期望修订号；修订号不等于当前值时
193	// 返回 ErrRevisionConflict，影子和审计均不改变。成功时返回新修订号。
194	//
195	// 配置校验、修订号判断、配置替换、审计与差异时间更新与批量修改共用同一
196	// 实现（checkDesiredMeta/checkDesiredRevision/applyDesired），仅校验次序
197	// 与错误消息格式保持各自既有形式。
198	func (s *Store) UpdateDesired(deviceID, operator string, at time.Time, revision uint64, config json.RawMessage) (uint64, error) {
199		s.mu.Lock()
200		defer s.mu.Unlock()
201		if err := s.checkOpen(); err != nil {
202			return 0, err
203		}
204		d, err := s.lookup(deviceID)
205		if err != nil {
206			return 0, err
207		}
208		if err := checkDesiredMeta(operator, at); err != nil {
209			return 0, err
210		}
211		cfg, err := validateConfig(config)
212		if err != nil {
213			return 0, err
214		}
215		if err := checkDesiredRevision(d, deviceID, revision); err != nil {
216			return 0, desiredSingleError(err.(errDesiredRevision))
217		}
218		var newRevision uint64
219		err = s.commit(func() error {
220			newRevision = applyDesired(d, deviceID, operator, at, "", cfg)
221			return nil
222		})
223		if err != nil {
224			return 0, err
225		}
226		return newRevision, nil
227	}
228	
229	// Report 处理设备上报。需携带正整数序号、时间、非空当前版本和完整配置。
230	// 更大序号更新上报并标为在线；相同序号且版本、配置、时间相同视为重复，
231	// 成功返回但不改变状态；相同序号内容不同或更小序号返回错误。
232	//
233	// 校验、序号判断与影子写入规则与安装/回滚成功的附带上报共用同一实现
234	// （checkReport/applyReport），仅错误类别保持各自公开的哨兵不变。
235	func (s *Store) Report(deviceID string, seq uint64, at time.Time, version string, config json.RawMessage) error {
236		s.mu.Lock()
237		defer s.mu.Unlock()
238		if err := s.checkOpen(); err != nil {
239			return err
240		}
241		d, err := s.lookup(deviceID)
242		if err != nil {
243			return err
244		}
245		in := reportInput{DeviceID: deviceID, Seq: seq, At: at, Version: version, Config: config}
246		cfg, verdict, err := checkReport(d, in, "")
247		if err != nil {
248			return reportPlainError(err.(errBadReport))
249		}
250		if verdict == reportDuplicate {
251			// 重复上报：成功返回，不写入影子，也不触发持久化。
252			return nil
253		}
254		return s.commit(func() error {
255			applyReport(d, in, cfg, verdict, at)
256			return nil
257		})
258	}
