260	// SetOffline 将设备标为离线。只改变在线状态，保留版本及双方配置。
261	func (s *Store) SetOffline(deviceID string) error {
262		s.mu.Lock()
263		defer s.mu.Unlock()
264		if err := s.checkOpen(); err != nil {
265			return err
266		}
267		d, err := s.lookup(deviceID)
268		if err != nil {
269			return err
270		}
271		return s.commit(func() error {
272			d.Online = false
273			return nil
274		})
275	}
