411	// diskStore 是存储文件的磁盘格式。
412	type diskStore struct {
413		Format    int                     `json:"format"`
414		Devices   map[string]diskState    `json:"devices"`
415		Versions  map[string]diskVersion  `json:"versions,omitempty"`
416		Campaigns map[string]diskCampaign `json:"campaigns,omitempty"`
417		Batches   map[string]diskBatch    `json:"batches,omitempty"`
418	}
419	
420	type diskState struct {
421		Version        string               `json:"version"`
422		Online         bool                 `json:"online"`
423		Revision       uint64               `json:"revision"`
424		Desired        json.RawMessage      `json:"desired"`
425		Reported       json.RawMessage      `json:"reported"`
426		LastSeq        uint64               `json:"lastSeq"`
427		LastReportTime time.Time            `json:"lastReportTime,omitempty"`
428		DiffSince      map[string]time.Time `json:"diffSince,omitempty"`
429		Audit          []diskAudit          `json:"audit,omitempty"`
430	}
431	
432	type diskAudit struct {
433		Operator  string          `json:"operator"`
434		Time      time.Time       `json:"time"`
435		Revision  uint64          `json:"revision"`
436		RequestID string          `json:"requestId,omitempty"`
437		Before    json.RawMessage `json:"before"`
438		After     json.RawMessage `json:"after"`
439	}
440	
441	func (s *Store) marshal() ([]byte, error) {
442		disk := diskStore{Format: storeFormat, Devices: make(map[string]diskState, len(s.devices))}
443		for id, d := range s.devices {
444			ds := diskState{
445				Version:        d.Version,
446				Online:         d.Online,
447				Revision:       d.Revision,
448				Desired:        cloneRaw(d.Desired),
449				Reported:       cloneRaw(d.Reported),
450				LastSeq:        d.LastSeq,
451				LastReportTime: d.LastReportTime,
452				DiffSince:      make(map[string]time.Time, len(d.DiffSince)),
453			}
454			for p, t := range d.DiffSince {
455				ds.DiffSince[p] = t
456			}
457			for _, rec := range d.Audit {
458				ds.Audit = append(ds.Audit, diskAudit{
459					Operator:  rec.Operator,
460					Time:      rec.Time,
461					Revision:  rec.Revision,
462					RequestID: rec.RequestID,
463					Before:    cloneRaw(rec.Before),
464					After:     cloneRaw(rec.After),
465				})
466			}
467			disk.Devices[id] = ds
468		}
469		disk.Versions = s.marshalVersions()
470		campaigns, err := s.marshalCampaigns()
471		if err != nil {
472			return nil, err
473		}
474		disk.Campaigns = campaigns
475		disk.Batches = s.marshalBatches()
476		data, err := json.Marshal(disk)
477		if err != nil {
478			return nil, fmt.Errorf("shadow: encode store: %w", err)
479		}
480		return data, nil
481	}
482	
483	// restore 从存储文件内容恢复状态。内容损坏或格式不识别时返回
484	// ErrCorruptStorage，绝不按空数据覆盖。
485	func (s *Store) restore(data []byte) error {
486		var disk diskStore
487		if err := json.Unmarshal(data, &disk); err != nil {
488			return fmt.Errorf("%w: %v", ErrCorruptStorage, err)
489		}
490		if disk.Format != storeFormat {
491			return fmt.Errorf("%w: unsupported format %d", ErrCorruptStorage, disk.Format)
492		}
493		devices := make(map[string]*deviceState, len(disk.Devices))
494		for id, ds := range disk.Devices {
495			if id == "" {
496				return fmt.Errorf("%w: empty device id", ErrCorruptStorage)
497			}
498			if _, ok := decodeObject(ds.Desired); !ok {
499				return fmt.Errorf("%w: device %s desired config invalid", ErrCorruptStorage, id)
500			}
501			if _, ok := decodeObject(ds.Reported); !ok {
502				return fmt.Errorf("%w: device %s reported config invalid", ErrCorruptStorage, id)
503			}
504			d := &deviceState{
505				Version:        ds.Version,
506				Online:         ds.Online,
507				Revision:       ds.Revision,
508				Desired:        cloneRaw(ds.Desired),
509				Reported:       cloneRaw(ds.Reported),
510				LastSeq:        ds.LastSeq,
511				LastReportTime: ds.LastReportTime,
512				DiffSince:      make(map[string]time.Time, len(ds.DiffSince)),
513			}
514			if err := d.validateLastReport(); err != nil {
515				return fmt.Errorf("%w: device %s %v", ErrCorruptStorage, id, err)
516			}
517			for p, t := range ds.DiffSince {
518				d.DiffSince[p] = t
519			}
520			for _, da := range ds.Audit {
521				if da.Operator == "" || da.Time.IsZero() || da.Revision == 0 {
522					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
523				}
524				if _, ok := decodeObject(da.Before); !ok {
525					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
526				}
527				if _, ok := decodeObject(da.After); !ok {
528					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
529				}
530				d.Audit = append(d.Audit, AuditRecord{
531					DeviceID:  id,
532					Operator:  da.Operator,
533					Time:      da.Time,
534					Revision:  da.Revision,
535					RequestID: da.RequestID,
536					Before:    cloneRaw(da.Before),
537					After:     cloneRaw(da.After),
538				})
539			}
540			// 审计必须能完整解释当前期望配置：修订号从 1 开始逐条连续到当前
541			// 修订号；首条修改前是登记时的空对象，每条修改后等于下一条修改前，
542			// 末条修改后等于当前期望配置。比较沿用配置的 JSON 语义，不要求
543			// 操作时间严格递增。修订号为 0 时审计必须为空、期望必须为空对象。
544			if uint64(len(d.Audit)) != d.Revision {
545				return fmt.Errorf("%w: device %s audit history does not cover revision %d",
546					ErrCorruptStorage, id, d.Revision)
547			}
548			expected := json.RawMessage(`{}`)
549			for i, rec := range d.Audit {
550				if rec.Revision != uint64(i+1) {
551					return fmt.Errorf("%w: device %s audit revision %d out of sequence",
552						ErrCorruptStorage, id, rec.Revision)
553				}
554				if !rawEqual(rec.Before, expected) {
555					return fmt.Errorf("%w: device %s audit revision %d broken chain",
556						ErrCorruptStorage, id, rec.Revision)
557				}
558				expected = rec.After
559			}
560			if !rawEqual(expected, d.Desired) {
561				return fmt.Errorf("%w: device %s desired config not explained by audit",
562					ErrCorruptStorage, id)
563			}
564			// 差异计时记录必须与双方当前配置重新计算出的差异完全一致：
565			// 每条实际差异都要有一条非零的首次出现时间，记录中也不能残留
566			// 当前已经没有差异的路径（父路径不能代替子路径，路径不同即使
567			// 条数相同也不行）。没有差异时允许不保存记录或保存空记录。
568			entries := computeDiff(d.Desired, d.Reported)
569			if len(entries) != len(d.DiffSince) {
570				return fmt.Errorf("%w: device %s diff times do not match current diff paths",
571					ErrCorruptStorage, id)
572			}
573			for _, e := range entries {
574				since, ok := d.DiffSince[e.Path]
575				if !ok {
576					return fmt.Errorf("%w: device %s diff %s missing first-seen time",
577						ErrCorruptStorage, id, e.Path)
578				}
579				if since.IsZero() {
580					return fmt.Errorf("%w: device %s diff %s has zero first-seen time",
581						ErrCorruptStorage, id, e.Path)
582				}
583			}
584			devices[id] = d
585		}
586		s.devices = devices
587		if err := s.restoreVersions(disk.Versions); err != nil {
588			return err
589		}
590		if err := s.restoreCampaigns(disk.Campaigns); err != nil {
591			return err
592		}
593		if err := s.restoreBatches(disk.Batches); err != nil {
594			return err
595		}
596		return nil
597	}
598

