465	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
466	//
467	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
468	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
469	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion；
470	// 开启回滚的活动还会在首次领取下载时把设备当时的当前版本锁定为回滚目标，
471	// 后续普通上报不改变它。
472	// 开启回滚且安装失败已被接受后，设备领取回滚操作：首次领取同样要求设备在线
473	// 且时间位于原维护窗口 [start, end) 内（不受批次放行影响），返回的操作带锁定
474	// 目标版本；离线或窗口外保留待办。回滚已领取但未完成时再次查询返回同一标识，
475	// 且可在窗口外、截止前提交结果。
476	// 已领取但未完成的操作（下载/安装/回滚）再次查询时返回同一标识，不要求在线或位于窗口内。
477	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
478	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
479	// 活动仍在执行、领取时间有效（非缺失、不倒退、早于截止）而设备自身的步骤已经结束
480	// （成功、失败、未执行，或回滚成功/失败）时，领取是纯拒绝：返回空操作和
481	// ErrDeviceFinished（可用 errors.Is 判断），不重新派发操作、不推进时间基线、
482	// 不改设备状态/阶段/原因/时间、不增加结果历史、不改设备影子与待办，也不落盘，
483	// 因而存储目录不可写时调用方拿到的仍是设备已结束的真实结果，而不是保存错误；
484	// 被拒绝的领取时间不会成为活动新的已接受时间，不影响随后更早时间的合法请求。
485	// 该判断只看设备是否终态，不依赖设备在线与否或领取时间是否落在维护窗口；
486	// 等待回滚与正在回滚不是终态、仍有未完成工作，不在此拒绝范围内。
487	// 活动已结束（无论因超时还是提前成功/失败结束、无论领取时间在原截止前、
488	// 恰好截止或截止后）时领取是纯拒绝：返回 ErrCampaignEnded，不推进时间基线、
489	// 不改活动结论、结束时间、设备状态与状态时间、结果历史和设备影子，也不落盘，
490	// 因此被拒绝的领取时间不会影响后续合法请求或重开存储后的倒退判断。
491	// 活动仍在执行而领取首次到达截止时间时保留原有截止处理：不派发操作，
492	// 全部未结束设备按阶段记为超时（等待或正在回滚的记回滚超时），已有终态
493	// 保持不变，以本次领取时间结束活动；此次结束时间仍参与后续倒退判断。
494	// 即使所选设备早已结束，截止处理仍按整个活动级联，本次实际改变进度仍需保存，
495	// 保存失败沿用整体回滚。
496	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
497		s.mu.Lock()
498		defer s.mu.Unlock()
499		if err := s.checkOpen(); err != nil {
500			return nil, err
501		}
502		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
503		if err != nil {
504			return nil, err
505		}
506		if at.IsZero() {
507			return nil, ErrInvalidTime
508		}
509		if at.Before(c.LastTime) {
510			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
511		}
512		if c.Ended {
513			// 已结束活动的领取是纯拒绝：不推进时间基线、不改状态、不落盘，
514			// 否则被拒绝的领取时间会把基线推过真正已接受的时间，
515			// 使随后本来合法的请求被误判为时间倒退。
516			return nil, ErrCampaignEnded
517		}
518		// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
519		// 即使查询的设备已有终态，其他未结束设备仍要级联超时；截止处理按整个
520		// 活动判断，优先于单设备的已结束拒绝。本次确实改变进度，仍需保存，
521		// 保存失败由 commit 整体回滚内存状态。
522		if !at.Before(c.Deadline) {
523			if err := s.commit(func() error {
524				c.LastTime = at
525				s.applyTimeout(c, at)
526				return nil
527			}); err != nil {
528				return nil, err
529			}
530			return nil, ErrCampaignEnded
531		}
532		// 设备自身步骤已结束（终态）而活动仍在等待其他设备：纯拒绝，不进入
533		// commit，因此不尝试保存、不替换存储文件，也不推进时间基线。等待回滚、
534		// 正在回滚不是终态，仍可领取回滚操作，不能归入这一拒绝。
535		if isTerminal(cd.Status) {
536			return nil, fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
537		}
538		var op *Operation
539		var reject error
540		err = s.commit(func() error {
541			c.LastTime = at
542			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
543			if stage, claimed := pendingStage(cd); claimed {
544				op = stageOperation(c, cd, stage)
545				return nil
546			}
547			// 安装失败已接受、等待回滚：回滚是该设备的善后操作，不受批次放行影响。
548			// 首次领取要求在线且位于原维护窗口 [start,end) 内；离线或窗口外保留待办。
549			if cd.Status == DeviceAwaitingRollback {
550				if !s.devices[deviceID].Online {
551					return nil
552				}
553				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
554					return nil
555				}
556				cd.Rollback.Claimed = true
557				cd.Rollback.ClaimedAt = at
558				cd.Status = DeviceRollingBack
559				cd.Phase = StageRollback
560				cd.At = at
561				op = stageOperation(c, cd, StageRollback)
562				return nil
563			}
564			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
565			if !s.batchOpen(c, cd) {
566				return nil
567			}
568			if !s.devices[deviceID].Online {
569				return nil // 离线保留待办，上线后继续
570			}
571			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
572				return nil // 窗口外不派发新操作；窗口为 [start, end)
573			}
574			if !cd.Download.Claimed {
575				// 首次领取下载前再次检查当前版本。
576				current := s.devices[deviceID].Version
577				if !containsString(s.versions[c.Target].AllowedFrom, current) {
578					reason := fmt.Sprintf("version %s is not compatible with target %s", current, c.Target)
579					// 该设备在下载阶段失败：领取即触发，记录阶段、原因和时间。
580					cd.Download.Claimed = true
581					cd.Download.ClaimedAt = at
582					cd.Download.HasResult = true
583					cd.Download.Success = false
584					cd.Download.Reason = reason
585					cd.Download.At = at
586					s.failDevice(c, cd, StageDownload, reason, at)
587					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
588					return nil
589				}
590				// 开启回滚时，把首次领取下载时设备的当前版本锁定为回滚目标；
591				// 此后普通上报不改变它，也不要求该版本另行登记为升级目标。
592				if c.RollbackOnFailure && cd.RollbackTarget == "" {
593					cd.RollbackTarget = current
594				}
595				cd.Download.Claimed = true
596				cd.Download.ClaimedAt = at
597				cd.Status = DeviceDownloading
598				cd.At = at
599				op = stageOperation(c, cd, StageDownload)
600				return nil
601			}
602			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
603			cd.Install.Claimed = true
604			cd.Install.ClaimedAt = at
605			cd.Status = DeviceInstalling
606			cd.At = at
607			op = stageOperation(c, cd, StageInstall)
608			return nil
609		})
610		if err != nil {
611			return nil, err
612		}
613		if reject != nil {
614			return nil, reject
615		}
616		return op, nil
617	}
618	
619	// stageOperation 构造某一阶段对外呈现（查询待办或领取返回）的操作描述。
620	// 同一（设备, 阶段）的描述只在这一处组装，保证查询到的待办与实际领取到的
621	// 操作信息一致：标识、活动、设备与阶段固定；仅回滚操作携带首次领取下载时
622	// 锁定的目标版本（普通上报不能改写它），下载与安装的目标版本始终为空。
623	func stageOperation(c *campaignState, cd *campaignDevice, stage string) *Operation {
624		op := &Operation{CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: stage}
625		switch stage {
626		case StageDownload:
627			op.ID = cd.Download.ID
628		case StageInstall:
629			op.ID = cd.Install.ID
630		case StageRollback:
631			op.ID = cd.Rollback.ID
632			op.TargetVersion = cd.RollbackTarget
633		}
634		return op
635	}
636	
637	// pendingStage 解析设备当前仍待完成的阶段（至多一个）及其是否已领取。
638	// 这是待办判定的唯一来源，查询与领取共用，避免同一阶段的操作信息分别维护：
639	// 已领取但尚无结果的下载/安装/回滚（claimed=true）；否则等待回滚时为尚未
640	// 领取的回滚；下载成功后为尚未领取的安装；其余非终态为尚未领取的下载。
641	// 设备已结束自己的步骤（终态）时返回空阶段。
642	func pendingStage(cd *campaignDevice) (stage string, claimed bool) {
643		switch {
644		case cd.Download.Claimed && !cd.Download.HasResult:
645			return StageDownload, true
646		case cd.Install.Claimed && !cd.Install.HasResult:
647			return StageInstall, true
648		case cd.Rollback.Claimed && !cd.Rollback.HasResult:
649			return StageRollback, true
650		case isTerminal(cd.Status):
651			return "", false
652		case cd.Status == DeviceAwaitingRollback:
653			return StageRollback, false
654		case cd.Download.HasResult:
655			// 下载已成功、安装尚未领取（ready）。
656			return StageInstall, false
657		default:
658			return StageDownload, false
659		}
660	}
661	
662	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
663	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
664		for _, other := range c.Devices {
665			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
666				return false
667			}
668		}
669		return true
670	}
671	
672	// SubmitResult 接收设备提交的操作结果。
673	//
674	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
675	// 改用不同结果、跳过未领取阶段、提交未领取的回滚、提交其他设备的操作、
676	// 活动结束后的新结果均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
677	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
678	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
679	// 回滚成功须附带版本等于锁定回滚目标的合规上报，影子与活动在同一次持久化中更新。
680	// 开启回滚的活动中，安装失败不直接结束设备，而是保留原失败原因与时间、
681	// 令设备等待回滚；回滚失败必须给出原因，设备以回滚失败结束且影子不变。
682	// 已领取且尚未接受结果的操作在截止时刻及以后提交时，结果已经迟到，
683	// 不校验附带上报与失败原因、不接收为操作结果：若提交前活动仍在执行，
684	// 本次作为首次触发截止处理——未结束设备全部超时（等待或正在回滚的记回滚
685	// 超时），活动以本次提交时间失败结束，返回 ErrCampaignEnded，本次确实推进
686	// 的时间仍参与后续倒退判断；若活动此前已因超时结束，则只返回 ErrCampaignEnded，
687	// 是不推进时间基线、不改结束时间与设备状态的纯拒绝，因此随后不早于结束时间的
688	// 合法时间不会因这次拒绝而被判为倒退。
689	// 普通设备上报不经过本方法，也不会推进活动。
690	func (s *Store) SubmitResult(res OperationResult) error {
691		s.mu.Lock()
692		defer s.mu.Unlock()
693		if err := s.checkOpen(); err != nil {
694			return err
695		}
696		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
697		if err != nil {
698			return err
699		}
700		if res.At.IsZero() {
701			return ErrInvalidTime
702		}
703		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
704		var stage string
705		var op *opState
706		switch res.OperationID {
707		case cd.Download.ID:
708			stage, op = StageDownload, &cd.Download
709		case cd.Install.ID:
710			stage, op = StageInstall, &cd.Install
711		case cd.Rollback.ID:
712			stage, op = StageRollback, &cd.Rollback
713		default:
714			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
715		}
716		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
717		// 不推进时间基线；不同结果冲突。均不改变状态。
718		if op.HasResult {
719			if resultMatches(op, res) {
720				return nil
721			}
722			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
723		}
724		if res.At.Before(c.LastTime) {
725			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
726		}
727		if !op.Claimed {
728			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段（含未领取的回滚）。
729			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
730		}
731		// 已领取且尚未接受结果的操作在截止时刻及以后提交：结果已经迟到，
732		// 不再接收为操作结果，也不校验附带上报或失败原因。
733		if !res.At.Before(c.Deadline) {
734			if c.Ended {
735				// 活动此前已因超时结束（显式推进或更早的迟到提交触发）：
736				// 本次拒绝是纯拒绝，不推进时间基线、不改结束时间、不改设备状态，
737				// 否则随后原本合法的时间会因这次拒绝而被判为倒退。
738				return ErrCampaignEnded
739			}
740			// 活动仍在执行，本次是首次触发截止处理：未结束设备全部超时
741			// （等待/正在回滚的记回滚超时），活动以失败结束，状态时间与活动
742			// 结束时间采用本次提交时间；这次确实推进的时间仍参与后续倒退判断。
743			if err := s.commit(func() error {
744				c.LastTime = res.At
745				s.applyTimeout(c, res.At)
746				return nil
747			}); err != nil {
748				return err
749			}
750			return ErrCampaignEnded
751		}
752		if !res.Success && res.Reason == "" {
753			return ErrInvalidReason
754		}
755		// 安装/回滚成功附带的设备上报与普通 Report 共用 checkReport 的同一套
756		// 规则（必填字段、版本约束、序号过旧/重复/冲突）；这里先校验并记下判定，
757		// 实际写入在下面的同一次 commit 内与活动、历史一起完成。附带上报任何
758		// 不合规都映射为 ErrInvalidReport，不改成普通上报的错误类别。
759		var repIn reportInput
760		var repCfg json.RawMessage
761		var repVerdict reportVerdict
762		if res.Success && (stage == StageInstall || stage == StageRollback) {
763			// 安装上报版本必须等于升级目标；回滚上报版本必须等于锁定的回滚目标。
764			wantVersion := c.Target
765			if stage == StageRollback {
766				wantVersion = cd.RollbackTarget
767			}
768			repIn = reportInput{
769				DeviceID: res.DeviceID,
770				Seq:      res.Seq,
771				At:       res.At,
772				Version:  res.Version,
773				Config:   res.Config,
774			}
775			var checkErr error
776			repCfg, repVerdict, checkErr = checkReport(s.devices[res.DeviceID], repIn, wantVersion)
777			if checkErr != nil {
778				return reportAttachedError(checkErr.(errBadReport))
779			}
780		}
781		var reject error
782		err = s.commit(func() error {
783			// 到达这里时提交时间早于截止（截止时刻及以后已在提交前处理）。
784			// 一致状态下持有已领取未完成操作的设备尚未终态、活动也不会结束，
785			// 此判断仅作为防御性兜底：活动结束后的新结果拒绝且不改状态。
786			if c.Ended {
787				reject = ErrCampaignEnded
788				return nil
789			}
790			if isTerminal(cd.Status) {
791				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
792				return nil
793			}
794			c.LastTime = res.At
795			op.HasResult = true
796			op.Success = res.Success
797			op.Reason = res.Reason
798			op.At = res.At
799			if !res.Success {
800				switch {
801				case stage == StageInstall && c.RollbackOnFailure:
802					// 安装失败：保留原因和时间，设备转入等待回滚（非终态）；
803					// 同批其他设备继续，后续批次立即记为未执行，活动暂不结束。
804					s.enterRollback(c, cd, res.Reason, res.At)
805				case stage == StageRollback:
806					// 回滚失败必须给出原因：设备以回滚失败结束且影子不变。
807					s.finishRollbackFailure(c, cd, res.Reason, res.At)
808				default:
809					s.failDevice(c, cd, stage, res.Reason, res.At)
810				}
811				return nil
812			}
813			switch stage {
814			case StageDownload:
815				cd.Status = DeviceReady
816				cd.Phase = StageInstall
817				cd.Reason = ""
818				cd.At = res.At
819			case StageInstall:
820				// 安装成功：附带上报与活动同时更新、一起持久化。
821				// 同序号的完全重复上报不重新写入影子（不刷新在线状态与差异时间）。
822				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
823				op.ResultSeq = res.Seq
824				op.ResultVersion = res.Version
825				op.ResultConfig = cloneRaw(res.Config)
826				cd.Status = DeviceSucceeded
827				cd.Phase = StageInstall
828				cd.Reason = ""
829				cd.At = res.At
830			case StageRollback:
831				// 回滚成功：按上报规则更新影子（版本回到锁定目标），同时推进回滚状态。
832				// 期望配置、修订号与审计保持不变；重复上报不重新写入影子。
833				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
834				op.ResultSeq = res.Seq
835				op.ResultVersion = res.Version
836				op.ResultConfig = cloneRaw(res.Config)
837				cd.Status = DeviceRollbackSucceeded
838				cd.Phase = StageRollback
839				cd.Reason = ""
840				cd.At = res.At
841			}
842			c.Results = append(c.Results, ResultRecord{
843				DeviceID:    cd.DeviceID,
844				OperationID: op.ID,
845				Stage:       stage,
846				Success:     true,
847				Version:     op.ResultVersion,
848				At:          res.At,
849			})
850			s.settle(c, res.At)
851			return nil
852		})
853		if err != nil {
854			return err
855		}
856		return reject
857	}
