859	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
860	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
861	// 使活动结束后的重复提交仍然有效。
862	func resultMatches(op *opState, res OperationResult) bool {
863		if op.Success != res.Success || op.Reason != res.Reason {
864			return false
865		}
866		if op.Success && op.ResultSeq != 0 {
867			return op.ResultSeq == res.Seq &&
868				op.ResultVersion == res.Version &&
869				rawEqual(op.ResultConfig, res.Config)
870		}
871		return true
872	}
873	
874	// failureResultRecord 按统一规则组装一次已接受失败结果的结果历史条目：
875	// 对应设备、该阶段的操作标识、失败标记以及首次接受的原因与发生时间。
876	// 下载失败、安装失败与回滚失败的历史条目只在这一处生成，共同记录要求
877	// 变化时不必分别改动几种失败处理。
878	func failureResultRecord(cd *campaignDevice, stage, reason string, at time.Time) ResultRecord {
879		return ResultRecord{
880			DeviceID:    cd.DeviceID,
881			OperationID: opIDFor(cd, stage),
882			Stage:       stage,
883			Success:     false,
884			Reason:      reason,
885			At:          at,
886		}
887	}
888	
889	// recordFailureResult 落实一次已接受失败结果的共同记录规则：设备的失败原因与
890	// 发生时间、以及结果历史中恰好一条失败记录只在这一处维护。失败结果本身不更新
891	// 设备版本、在线状态或上报配置，也不修改期望配置、修订号及审计；失败后设备
892	// 走向（直接失败/等待回滚/回滚失败）、批次级联与活动是否结束仍由各调用处按
893	// 现有差异分别处理。
894	func (s *Store) recordFailureResult(c *campaignState, cd *campaignDevice, stage, reason string, at time.Time) {
895		cd.Reason = reason
896		cd.At = at
897		c.Results = append(c.Results, failureResultRecord(cd, stage, reason, at))
898	}
899	
900	// enterRollback 在开启回滚的活动中处理已接受的安装失败：
901	// 按统一规则记录原安装失败的原因与时间，令设备等待回滚（非终态）；
902	// 同批其他设备可继续，后续批次立即记为未执行，但活动暂不结束。
903	func (s *Store) enterRollback(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
904		s.recordFailureResult(c, cd, StageInstall, reason, at)
905		cd.Status = DeviceAwaitingRollback
906		cd.Phase = StageRollback
907		skipLaterBatches(c, cd, at)
908		// 不结束活动：设备进入非终态的等待回滚，活动要等其回滚结束。
909	}
910	
911	// finishRollbackFailure 处理已接受的回滚失败：必须给出原因，
912	// 按统一规则记录回滚失败后设备以回滚失败结束，影子不变
913	// （失败结果不附带、不应用上报）。
914	func (s *Store) finishRollbackFailure(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
915		s.recordFailureResult(c, cd, StageRollback, reason, at)
916		cd.Status = DeviceRollbackFailed
917		cd.Phase = StageRollback
918		s.settle(c, at)
919	}
920	
921	// skipLaterBatches 把后续批次中尚未结束的设备立即记为未执行。
922	func skipLaterBatches(c *campaignState, cd *campaignDevice, at time.Time) {
923		for _, other := range c.Devices {
924			if other.Batch > cd.Batch && !isTerminal(other.Status) {
925				other.Status = DeviceSkipped
926				other.Phase = pendingPhase(other)
927				other.Reason = "not executed: previous batch failed"
928				other.At = at
929			}
930		}
931	}
932	
933	// failDevice 将设备记为失败：按统一规则记录阶段、原因和时间；后续批次全部
934	// 记为未执行，本批其他设备继续。若全部设备已到终态，则活动以失败结束。
935	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
936		s.recordFailureResult(c, cd, phase, reason, at)
937		cd.Status = DeviceFailed
938		cd.Phase = phase
939		skipLaterBatches(c, cd, at)
940		s.settle(c, at)
941	}
