1113		// InstallFailReason/InstallFailAt 是已接受的安装失败的原因与时间，
1114		// 进入回滚后仍保留原值，便于与回滚结果分别查看。
1115		InstallFailReason string
1116		InstallFailAt     time.Time
1117		// RollbackResult 表示是否已接受回滚结果。
1118		RollbackResult bool
1119		// RollbackSuccess 表示已接受的回滚结果是否成功。
1120		RollbackSuccess bool
1121		// RollbackReason/RollbackAt 是回滚结果（成功或失败）的原因与时间。
1122		RollbackReason string
1123		RollbackAt     time.Time
1124	}
