183	// restoreCampaigns 恢复活动并做一致性校验。版本、设备引用、操作标识、
184	// 结果历史都必须自洽，否则整个存储拒绝打开。
185	func (s *Store) restoreCampaigns(disk map[string]diskCampaign) error {
186		out := make(map[string]*campaignState, len(disk))
187		for id, dc := range disk {
188			if id == "" || dc.ID != id {
189				return fmt.Errorf("%w: campaign id mismatch", ErrCorruptStorage)
190			}
191			if dc.Operator == "" || dc.Target == "" || dc.BatchSize <= 0 {
192				return fmt.Errorf("%w: campaign %s invalid", ErrCorruptStorage, id)
193			}
194			if dc.CreatedAt.IsZero() || dc.WindowStart.IsZero() || dc.WindowEnd.IsZero() || dc.Deadline.IsZero() {
195				return fmt.Errorf("%w: campaign %s missing time", ErrCorruptStorage, id)
196			}
197			if !dc.WindowStart.Before(dc.WindowEnd) || !dc.Deadline.After(dc.CreatedAt) {
198				return fmt.Errorf("%w: campaign %s invalid time range", ErrCorruptStorage, id)
199			}
200			if _, ok := s.versions[dc.Target]; !ok {
201				return fmt.Errorf("%w: campaign %s target %s missing", ErrCorruptStorage, id, dc.Target)
202			}
203			if dc.Status != CampaignRunning && dc.Status != CampaignSucceeded && dc.Status != CampaignFailed {
204				return fmt.Errorf("%w: campaign %s bad status", ErrCorruptStorage, id)
205			}
206			if dc.IDScheme != opIDSchemeLegacy && dc.IDScheme != opIDSchemeV2 {
207				return fmt.Errorf("%w: campaign %s unknown operation id scheme", ErrCorruptStorage, id)
208			}
209			if dc.Ended == (dc.Status == CampaignRunning) {
210				return fmt.Errorf("%w: campaign %s ended/status mismatch", ErrCorruptStorage, id)
211			}
212			if len(dc.Devices) == 0 {
213				return fmt.Errorf("%w: campaign %s has no devices", ErrCorruptStorage, id)
214			}
215			c := &campaignState{
216				ID:                dc.ID,
217				Operator:          dc.Operator,
218				Target:            dc.Target,
219				CreatedAt:         dc.CreatedAt,
220				BatchSize:         dc.BatchSize,
221				WindowStart:       dc.WindowStart,
222				WindowEnd:         dc.WindowEnd,
223				Deadline:          dc.Deadline,
224				RollbackOnFailure: dc.RollbackOnFailure,
225				idScheme:          dc.IDScheme,
226				LastTime:          dc.LastTime,
227				Status:            dc.Status,
228				Ended:             dc.Ended,
229				EndedAt:           dc.EndedAt,
230				index:             map[string]int{},
231			}
232			// 旧记录可能没有时间基线：缺省（零值）时仍以创建时间作为基线。
233			// 基线与各业务记录时间是否自洽在设备与历史全部恢复后统一检查。
234			if c.LastTime.IsZero() {
235				c.LastTime = c.CreatedAt
236			}
237			seen := map[string]bool{}
238			// expected 按操作标识收集每个已有结果（HasResult）的下载/安装/回滚
239			// 操作所对应的唯一应有历史条目，随后与保存的结果历史逐条对账。
240			expected := map[string]expectedHist{}
241			for i, dd := range dc.Devices {
242				if dd.DeviceID == "" || seen[dd.DeviceID] {
243					return fmt.Errorf("%w: campaign %s device list invalid", ErrCorruptStorage, id)
244				}
245				seen[dd.DeviceID] = true
246				if _, ok := s.devices[dd.DeviceID]; !ok {
247					return fmt.Errorf("%w: campaign %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
248				}
249				if dd.Batch != i/dc.BatchSize {
250					return fmt.Errorf("%w: campaign %s batch mismatch", ErrCorruptStorage, id)
251				}
252				if !validDeviceStatus(dd.Status) {
253					return fmt.Errorf("%w: campaign %s bad device status", ErrCorruptStorage, id)
254				}
255				if dd.Phase != StageDownload && dd.Phase != StageInstall && dd.Phase != StageRollback {
256					return fmt.Errorf("%w: campaign %s bad phase", ErrCorruptStorage, id)
257				}
258				if dc.IDScheme == opIDSchemeV2 {
259					// 新方案：标识必须是无歧义编码且恰好归属本活动、本设备、本阶段。
260					if !validV2OpID(dd.Download.ID, id, dd.DeviceID, StageDownload) ||
261						!validV2OpID(dd.Install.ID, id, dd.DeviceID, StageInstall) ||
262						!validV2OpID(dd.Rollback.ID, id, dd.DeviceID, StageRollback) {
263						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
264					}
265				} else {
266					wantDL := operationID(id, dd.DeviceID, StageDownload)
267					wantIN := operationID(id, dd.DeviceID, StageInstall)
268					wantRB := operationID(id, dd.DeviceID, StageRollback)
269					if dd.Download.ID != wantDL || dd.Install.ID != wantIN {
270						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
271					}
272					if dc.RollbackOnFailure {
273						if dd.Rollback.ID != wantRB {
274							return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
275						}
276					} else if dd.Rollback.ID != "" && dd.Rollback.ID != wantRB {
277						// 未开启回滚的旧活动：回滚标识允许缺省或等于旧稳定标识。
278						return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
279					}
280				}
281				if !dc.RollbackOnFailure {
282					// 未开启回滚的活动（含旧存储）不得残留任何回滚进展。
283					if dd.RollbackTarget != "" ||
284						dd.Rollback.Claimed || dd.Rollback.HasResult ||
285						dd.Status == DeviceAwaitingRollback || dd.Status == DeviceRollingBack ||
286						dd.Phase == StageRollback || isRollbackTerminal(dd.Status) {
287						return fmt.Errorf("%w: campaign %s rollback state in non-rollback campaign", ErrCorruptStorage, id)
288					}
289				}
290				// 终态设备必须带时间；失败还须带阶段与原因。
291				if isTerminal(dd.Status) && dd.At.IsZero() {
292					return fmt.Errorf("%w: campaign %s terminal without time", ErrCorruptStorage, id)
293				}
294				if dd.Status == DeviceFailed && dd.Reason == "" {
295					return fmt.Errorf("%w: campaign %s failure without reason", ErrCorruptStorage, id)
296				}
297				if (dd.Status == DeviceRollbackFailed || dd.Status == DeviceRollbackTimeout ||
298					dd.Status == DeviceAwaitingRollback) && dd.Reason == "" {
299					return fmt.Errorf("%w: campaign %s rollback without reason", ErrCorruptStorage, id)
300				}
301				if dd.Status == DeviceSucceeded &&
302					!(dd.Download.HasResult && dd.Download.Success && dd.Install.HasResult && dd.Install.Success) {
303					return fmt.Errorf("%w: campaign %s succeeded device without results", ErrCorruptStorage, id)
304				}
305				if dd.Status == DeviceFailed {
306					failedOp := dd.Download
307					if dd.Phase == StageInstall {
308						failedOp = dd.Install
309					}
310					if !failedOp.HasResult || failedOp.Success {
311						return fmt.Errorf("%w: campaign %s failed device without failed result", ErrCorruptStorage, id)
312					}
313				}
314				// pending（等待下载）与 downloading（下载中）都必须停留在下载阶段，
315				// 且只能依据本设备在本活动保存的下载操作记录核对。
316				if err := validateDownloadStageDisk(id, dd); err != nil {
317					return err
318				}
319				// ready（等待安装）与 installing（正在安装）都必须停留在安装阶段，
320				// 且只能依据本设备在本活动保存的下载/安装操作记录核对。
321				if err := validateInstallStageDisk(id, dd); err != nil {
322					return err
323				}
324				ops := []diskOp{dd.Download, dd.Install}
325				if dc.RollbackOnFailure {
326					ops = append(ops, dd.Rollback)
327				}
328				for _, o := range ops {
329					if o.HasResult {
330						if !o.Claimed {
331							return fmt.Errorf("%w: campaign %s unclaimed result", ErrCorruptStorage, id)
332						}
333						if o.At.IsZero() {
334							return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
335						}
336						if !o.Success && o.Reason == "" {
337							return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
338						}
339					}
340					if o.Claimed && o.ClaimedAt.IsZero() {
341						return fmt.Errorf("%w: campaign %s claim without time", ErrCorruptStorage, id)
342					}
343				}
344				if dd.Install.HasResult && !(dd.Download.HasResult && dd.Download.Success) {
345					return fmt.Errorf("%w: campaign %s install before download", ErrCorruptStorage, id)
346				}
347				if dd.Install.Claimed && !(dd.Download.HasResult && dd.Download.Success) {
348					return fmt.Errorf("%w: campaign %s install claimed before download", ErrCorruptStorage, id)
349				}
350				if dd.Install.HasResult && dd.Install.Success {
351					if dd.Install.ResultVersion != dc.Target {
352						return fmt.Errorf("%w: campaign %s install version mismatch", ErrCorruptStorage, id)
353					}
354					if _, ok := decodeObject(dd.Install.ResultConfig); !ok {
355						return fmt.Errorf("%w: campaign %s install config invalid", ErrCorruptStorage, id)
356					}
357					if err := checkSuccessReport(id, dd, dd.Install, StageInstall, s.devices[dd.DeviceID]); err != nil {
358						return err
359					}
360				}
361				if dc.RollbackOnFailure {
362					if err := validateRollbackDisk(id, dd); err != nil {
363						return err
364					}
365				}
366				if dd.Rollback.HasResult && dd.Rollback.Success {
367					// 未开启回滚的活动存在回滚结果已在上方拒绝；这里只需核对
368					// 开启回滚的活动中已接受的回滚成功记录。
369					if err := checkSuccessReport(id, dd, dd.Rollback, StageRollback, s.devices[dd.DeviceID]); err != nil {
370						return err
371					}
372				}
373				rbOp := decodeOp(dd.Rollback)
374				if !dc.RollbackOnFailure {
375					// 与创建路径一致：内存中始终持有本方案稳定的回滚操作标识。
376					if dc.IDScheme == opIDSchemeV2 {
377						rbOp = opState{ID: dd.Rollback.ID}
378					} else {
379						rbOp = opState{ID: operationID(id, dd.DeviceID, StageRollback)}
380					}
381				}
382				cd := &campaignDevice{
383					DeviceID:       dd.DeviceID,
384					Batch:          dd.Batch,
385					Status:         dd.Status,
386					Phase:          dd.Phase,
387					Reason:         dd.Reason,
388					At:             dd.At,
389					Download:       decodeOp(dd.Download),
390					Install:        decodeOp(dd.Install),
391					Rollback:       rbOp,
392					RollbackTarget: dd.RollbackTarget,
393				}
394				c.index[cd.DeviceID] = len(c.Devices)
395				c.Devices = append(c.Devices, cd)
396				// 每个已有结果的操作都应当恰好对应一条结果历史；
397				// 已领取未完成、超时或因前批失败而未执行的阶段没有结果，不入账。
398				addExpected := func(o diskOp, stage string) {
399					if !o.HasResult {
400						return
401					}
402					expected[o.ID] = expectedHist{deviceID: dd.DeviceID, stage: stage, op: o}
403				}
404				addExpected(dd.Download, StageDownload)
405				addExpected(dd.Install, StageInstall)
406				if dc.RollbackOnFailure {
407					addExpected(dd.Rollback, StageRollback)
408				}
409			}
410			// seenHistory 记录已经与保存历史对过账的操作标识。
411			seenHistory := map[string]bool{}
412			var prevAt time.Time
413			for i, dr := range dc.Results {
414				if dr.At.IsZero() {
415					return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
416				}
417				// 历史按接受顺序保存：时间不得倒退；同一时刻按保存次序排列。
418				if i > 0 && dr.At.Before(prevAt) {
419					return fmt.Errorf("%w: campaign %s result history out of order", ErrCorruptStorage, id)
420				}
421				prevAt = dr.At
422				if _, ok := c.index[dr.DeviceID]; !ok {
423					return fmt.Errorf("%w: campaign %s result device mismatch", ErrCorruptStorage, id)
424				}
425				if dr.Stage != StageDownload && dr.Stage != StageInstall && dr.Stage != StageRollback {
426					return fmt.Errorf("%w: campaign %s result stage invalid", ErrCorruptStorage, id)
427				}
428				if dr.Stage == StageRollback && !dc.RollbackOnFailure {
429					return fmt.Errorf("%w: campaign %s rollback result in non-rollback campaign", ErrCorruptStorage, id)
430				}
431				if dc.IDScheme == opIDSchemeLegacy {
432					// 旧方案标识可按（活动, 设备, 阶段）直接重算；新方案标识的
433					// 归属已在设备操作校验中确认，这里靠下方的历史对账锚定。
434					if wantOp := operationID(id, dr.DeviceID, dr.Stage); dr.OperationID != wantOp {
435						return fmt.Errorf("%w: campaign %s result op id mismatch", ErrCorruptStorage, id)
436					}
437				}
438				if seenHistory[dr.OperationID] {
439					return fmt.Errorf("%w: campaign %s duplicated result history", ErrCorruptStorage, id)
440				}
441				seenHistory[dr.OperationID] = true
442				// 历史必须对应该设备该阶段实际已有的结果：多出记录、设备或阶段不符
443				// 都按损坏处理，不能通过删历史或补结果把矛盾隐藏起来。
444				want, ok := expected[dr.OperationID]
445				if !ok {
446					return fmt.Errorf("%w: campaign %s result history without operation result", ErrCorruptStorage, id)
447				}
448				if want.deviceID != dr.DeviceID || want.stage != dr.Stage {
449					return fmt.Errorf("%w: campaign %s result history stage mismatch", ErrCorruptStorage, id)
450				}
451				if !dr.Success && dr.Reason == "" {
452					return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
453				}
454				o := want.op
455				if o.Success != dr.Success {
456					return fmt.Errorf("%w: campaign %s result history success mismatch", ErrCorruptStorage, id)
457				}
458				// 失败原因必须一致。成功结果的原因不进入历史（提交路径亦不拒绝
459				// 成功结果附带原因），故只对失败结果比对原因。
460				if !o.Success && o.Reason != dr.Reason {
461					return fmt.Errorf("%w: campaign %s result history reason mismatch", ErrCorruptStorage, id)
462				}
463				// 时间按同一时刻判断，不因时区表示不同而冲突。
464				if !o.At.Equal(dr.At) {
465					return fmt.Errorf("%w: campaign %s result history time mismatch", ErrCorruptStorage, id)
466				}
467				// 安装或回滚成功时记录的版本必须与当次操作接受的版本一致。
468				if dr.Success && (dr.Stage == StageInstall || dr.Stage == StageRollback) {
469					if dr.Version != o.ResultVersion || dr.Version == "" {
470						return fmt.Errorf("%w: campaign %s result history version mismatch", ErrCorruptStorage, id)
471					}
472				} else if dr.Version != "" {
473					// 下载成功及任何失败结果都不携带版本。
474					return fmt.Errorf("%w: campaign %s result history with unexpected version", ErrCorruptStorage, id)
475				}
476				c.Results = append(c.Results, ResultRecord{
477					DeviceID:    dr.DeviceID,
478					OperationID: dr.OperationID,
479					Stage:       dr.Stage,
480					Success:     dr.Success,
481					Reason:      dr.Reason,
482					Version:     dr.Version,
483					At:          dr.At,
484				})
485			}
486			// 反向对账：每个已有结果的操作都必须恰好有一条历史；缺少记录即损坏。
487			for opID, want := range expected {
488				if !seenHistory[opID] {
489					return fmt.Errorf("%w: campaign %s device %s %s result missing history",
490						ErrCorruptStorage, id, want.deviceID, want.stage)
491				}
492			}
493			// 活动整体结论必须与设备进度一致：与接收设备结果时的 settle 共用
494			// campaignConclusion 的同一套结论规则——任一设备仍处于非终态（等待下载、
495			// 下载中、等待安装、安装中、等待回滚、回滚中），活动必须 running 且
496			// Ended 为 false；全部设备终态时活动必须已结束，且只有每台设备都
497			// succeeded 才能 succeeded，其余组合（失败、超时、未执行，以及回滚
498			// 成功/失败/超时——回滚成功只是恢复原版本，不算本次升级成功）只能
499			// failed。设备离线或维护窗口结束不改变这一判断。
500			wantEnded, wantStatus := campaignConclusion(c)
501			if !wantEnded {
502				if c.Ended || c.Status != wantStatus {
503					return fmt.Errorf("%w: campaign %s ended while devices unfinished", ErrCorruptStorage, id)
504				}
505			} else {
506				if !c.Ended || c.Status != wantStatus {
507					return fmt.Errorf("%w: campaign %s status %s does not match device results",
508						ErrCorruptStorage, id, c.Status)
509				}
510			}
511			// 批次放行顺序必须与保存的升级结果自洽：任一设备首次领取下载时，
512			// 较早批次的每台设备都必须已经首次接受“安装成功”结果，且其成功
513			// 时间不晚于该次下载领取时间。只看活动保存的结果，不看设备当前在线
514			// 状态或当前版本；下载成功、安装中、安装失败后等待回滚、已回滚等
515			// 都不算放行。该核对对仍在执行和已结束的活动都生效，下载后来的
516			// 成功、失败或超时不能掩盖首次领取时越批的矛盾。
517			if err := checkCampaignBatchRelease(id, c); err != nil {
518				return err
519			}
520			// 每个已领取操作的首次领取时间必须落在活动保存的原维护窗口内；
521			// 窗口外的首次领取不能当作有效进度接受，也不能靠挪动领取时间、
522			// 撤销领取或重写进度来消除矛盾。
523			if err := checkCampaignClaimWindow(id, c); err != nil {
524				return err
525			}
526			// 时间基线必须能解释全部已存在的业务记录，否则重开后本应被拒绝的
527			// 旧时间请求又能推进活动。不能抬高基线或改写任何记录来掩盖矛盾。
528			if err := checkCampaignTimeBaseline(id, c); err != nil {
529				return err
530			}
531			// 已接受结果的操作，其首次结果发生时间不得早于该操作自己的首次领取
532			// 时间；结果先于领取发生在因果上不可能，不能靠其他设备的领取时间、
533			// 设备影子的最近上报时间或活动结束时间把它“合法化”。
534			if err := checkCampaignResultOrder(id, c); err != nil {
535				return err
536			}
537			// 已接受结果的操作，其首次结果发生时间还必须严格早于活动截止时间；
538			// 截止时刻及以后正常提交路径不再接收结果，已有存储中的迟到结果不能
539			// 当作有效进度读取。
540			if err := checkCampaignResultDeadline(id, c); err != nil {
541				return err
542			}
543			out[id] = c
544		}
545		// 设备不能同时参加多个未结束活动。
546		busy := map[string]string{}
547		for id, c := range out {
548			if c.Ended {
549				continue
550			}
551			for _, cd := range c.Devices {
552				if other, ok := busy[cd.DeviceID]; ok {
553					return fmt.Errorf("%w: device %s in active campaigns %s and %s",
554						ErrCorruptStorage, cd.DeviceID, other, id)
555				}
556				busy[cd.DeviceID] = id
557			}
558		}
559		s.campaigns = out
560		return nil
561	}
562	
563	// checkCampaignBatchRelease 核对活动的批次放行顺序与保存的升级结果自洽：
564	// 任一已经领取过下载的设备，在其首次领取下载时，所有较早批次的设备都必须
565	// 已经成功完成安装，且每台前序设备首次接受安装成功结果的时间不晚于该次
566	// 下载的首次领取时间。只按活动保存的升级结果判断：设备当前是否在线、当前
567	// 版本是否恰好等于目标版本都不能替代前序安装成功；前序设备仅下载成功、
568	// 正在安装、安装失败后等待回滚或已经回滚成功均不满足放行条件。
569	// 尚未领取下载的设备（正常等待后批、因前批失败而未执行、未领取即随截止
570	// 超时）不参与核对，也不能仅因前批没有成功而拒绝。时间按同一时刻比较，
571	// 时区写法不同不视为矛盾；同一时刻合法。核对对仍在执行和已结束的活动都
572	// 生效，下载后来成功、失败或超时都不能掩盖首次领取时越过前批的问题。
573	func checkCampaignBatchRelease(campaignID string, c *campaignState) error {
574		for _, cd := range c.Devices {
575			if !cd.Download.Claimed || cd.Download.ClaimedAt.IsZero() {
576				continue
577			}
578			claimedAt := cd.Download.ClaimedAt
579			for _, prev := range c.Devices {
580				if prev.Batch >= cd.Batch {
581					// 同批设备各自推进，不等待同批其他设备；更晚批次不相关。
582					continue
583				}
584				if !(prev.Install.HasResult && prev.Install.Success) {
585					return fmt.Errorf("%w: campaign %s device %s download claimed while previous-batch device %s not installed",
586						ErrCorruptStorage, campaignID, cd.DeviceID, prev.DeviceID)
587				}
588				// time.Time 的比较按绝对时刻进行，不因时区写法不同而拒绝
589				// 相同时刻；安装成功时刻晚于下载领取时刻即属越批领取，相等合法。
590				if prev.Install.At.After(claimedAt) {
591					return fmt.Errorf("%w: campaign %s device %s download claimed at %s before device %s install succeeded at %s",
592						ErrCorruptStorage, campaignID, cd.DeviceID,
593						claimedAt.Format(time.RFC3339Nano), prev.DeviceID, prev.Install.At.Format(time.RFC3339Nano))
594				}
595			}
596		}
597		return nil
598	}
599	
600	// checkCampaignClaimWindow 核对每个已领取的下载/安装/回滚操作的首次领取时间
601	// 都落在活动保存的原维护窗口 [start, end) 内：开始时刻包含、结束时刻不包含。
602	// 首次领取必须遵守维护窗口——早于开始或恰好到达、晚于结束的领取记录都使整个
603	// 存储损坏，即使其余状态与结果历史完全自洽、活动仍在执行或已成功/失败结束、
604	// 该操作后来成功、失败或超时，也不能把窗口外的首次领取当作有效进度接受，
605	// 更不能通过挪动领取时间、撤销领取、删去活动或重写进度来消除矛盾。
606	// 这项核对只针对真正首次领取的时刻：尚未领取的操作没有领取时间（等待下载、
607	// 等待安装、等待回滚及未领取便结束的记录），属正常缺省，不参与核对；未开启
608	// 回滚的活动内存中只有缺省的回滚操作标识，不算已领取。已经在窗口内领取的
609	// 操作，后来在窗口外的重复查询、截止前的结果接受以及活动结束时间都不要求
610	// 重新满足窗口。比较按绝对时刻进行，时区写法不同不视为矛盾。
611	func checkCampaignClaimWindow(campaignID string, c *campaignState) error {
612		for _, cd := range c.Devices {
613			ops := []struct {
614				stage string
615				op    *opState
616			}{
617				{StageDownload, &cd.Download},
618				{StageInstall, &cd.Install},
619				{StageRollback, &cd.Rollback},
620			}
621			for _, item := range ops {
622				if !item.op.Claimed {
623					continue
624				}
625				at := item.op.ClaimedAt
626				// 窗口为 [start, end)：恰好到达开始合法，恰好到达结束不合法。
627				// time.Time 的比较按绝对时刻进行，同一时刻的不同时区写法结果相同。
628				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
629					return fmt.Errorf("%w: campaign %s device %s %s first claimed at %s outside maintenance window [%s, %s)",
630						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
631						at.Format(time.RFC3339Nano),
632						c.WindowStart.Format(time.RFC3339Nano),
633						c.WindowEnd.Format(time.RFC3339Nano))
634				}
635			}
636		}
637		return nil
638	}
