640	// checkCampaignTimeBaseline 校验活动时间基线（已接受的最新时间）与保存的
641	// 业务记录自洽：基线必须不早于创建时间、任一设备已经领取下载/安装/回滚的
642	// 时间、任一操作首次接受结果的时间、设备当前状态中已记录的时间；活动已结束
643	// 时还必须不早于保存的结束时间。只比较确实存在的记录：尚未领取的操作没有
644	// 领取时间、尚未接受结果的操作没有结果时间、新建且尚未推进的设备允许没有
645	// 状态时间，这些正常缺省值不导致打开失败。比较按绝对时刻进行，相等合法。
646	func checkCampaignTimeBaseline(campaignID string, c *campaignState) error {
647		baseline := c.LastTime
648		bad := func(format string, args ...any) error {
649			msg := fmt.Sprintf(format, args...)
650			return fmt.Errorf("%w: campaign %s time baseline %s %s",
651				ErrCorruptStorage, campaignID, baseline.Format(time.RFC3339Nano), msg)
652		}
653		if baseline.Before(c.CreatedAt) {
654			return bad("before creation time %s", c.CreatedAt.Format(time.RFC3339Nano))
655		}
656		if c.Ended && !c.EndedAt.IsZero() && baseline.Before(c.EndedAt) {
657			return bad("before end time %s", c.EndedAt.Format(time.RFC3339Nano))
658		}
659		for _, cd := range c.Devices {
660			if !cd.At.IsZero() && baseline.Before(cd.At) {
661				return bad("before device %s state time %s",
662					cd.DeviceID, cd.At.Format(time.RFC3339Nano))
663			}
664			// 已领取（含尚未完成）的操作一定接受过携带领取时刻的请求；
665			// 已接受结果的操作还必须比较首次接受结果的时间。未领取/未接受
666			// 的操作对应时间为零值，属正常缺省，跳过比较。
667			ops := []struct {
668				stage string
669				op    *opState
670			}{
671				{StageDownload, &cd.Download},
672				{StageInstall, &cd.Install},
673				{StageRollback, &cd.Rollback},
674			}
675			for _, item := range ops {
676				if !item.op.ClaimedAt.IsZero() && baseline.Before(item.op.ClaimedAt) {
677					return bad("before device %s %s claim time %s",
678						cd.DeviceID, item.stage, item.op.ClaimedAt.Format(time.RFC3339Nano))
679				}
680				if item.op.HasResult && !item.op.At.IsZero() && baseline.Before(item.op.At) {
681					return bad("before device %s %s result time %s",
682						cd.DeviceID, item.stage, item.op.At.Format(time.RFC3339Nano))
683				}
684			}
685		}
686		return nil
687	}
688	
689	// checkCampaignResultOrder 校验每个已经接受结果的下载/安装/回滚操作，其首次
690	// 结果发生时间都不早于该操作自己的首次领取时间：同一活动、同一设备、同一阶段
691	// 的两个时刻直接比较，成功与失败适用同一规则。结果先于领取在因果上不可能，
692	// 必须使整个存储拒绝打开；不能用其他设备的领取时间、设备影子的最近上报时间、
693	// 活动的最新时间或结束时间替代这两个时刻，也不能通过修改时间、删除结果历史、
694	// 撤销领取或改变设备状态让记录变得合法。后来安装成功或回滚完成同样不能掩盖
695	// 早先阶段的矛盾，因此该核对对仍在执行和已结束的活动都生效。
696	// 只比较该操作自己确实存在的两个时刻：尚未接受结果（含已领取未完成、随后因
697	// 截止超时）的操作没有结果时间，尚未领取的等待步骤没有领取时间，均属正常
698	// 缺省，跳过核对。首次领取时因版本不兼容而直接形成的下载失败，领取与失败
699	// 可以是同一时刻；两时刻相等合法。已领取操作在窗口结束后、截止前提交结果
700	// 不受限制——本核对不要求结果落在维护窗口内。比较按绝对时刻进行，时区写法
701	// 不同不视为矛盾。重复提交不覆盖首次记录，这里使用的就是首次接受的两个时刻。
702	func checkCampaignResultOrder(campaignID string, c *campaignState) error {
703		for _, cd := range c.Devices {
704			ops := []struct {
705				stage string
706				op    *opState
707			}{
708				{StageDownload, &cd.Download},
709				{StageInstall, &cd.Install},
710				{StageRollback, &cd.Rollback},
711			}
712			for _, item := range ops {
713				o := item.op
714				// 未接受结果（含已领取未完成、超时）或未领取的操作不参与核对：
715				// HasResult 为 true 时上方的操作校验已保证 Claimed 且两个时间非零。
716				if !o.HasResult {
717					continue
718				}
719				// time.Time 的比较按绝对时刻进行：结果早于首次领取即损坏，
720				// 相同时刻的不同时区写法结果相同，相等合法。
721				if o.At.Before(o.ClaimedAt) {
722					return fmt.Errorf("%w: campaign %s device %s %s result at %s before first claim at %s",
723						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
724						o.At.Format(time.RFC3339Nano), o.ClaimedAt.Format(time.RFC3339Nano))
725				}
726			}
727		}
728		return nil
729	}
