731	// checkCampaignResultDeadline 校验每个已经接受结果的下载/安装/回滚操作，其首次
732	// 结果发生时间都严格早于所属活动的截止时间：正常提交路径在截止时刻及以后不再
733	// 把结果接收为操作结果（已领取未完成的操作随截止记为超时），因此已有存储中
734	// 等于或晚于截止的结果时间不可能由正常提交产生，必须使整个存储拒绝打开。
735	// 成功与失败适用同一规则；恰好等于截止时间也属于迟到。比较按绝对时刻进行，
736	// 时区写法不同不改变判断。该核对对仍在执行和已结束的活动都生效：设备后来
737	// 安装成功、回滚完成或当前版本恰好等于目标版本，都不能让早先的迟到结果合法。
738	// 只比较操作自己确实保存的结果时间：已领取但尚无结果、随后因截止而超时的操作
739	// 没有结果时间，属正常缺省，不参与核对；活动的超时状态时间与结束时间可以等于
740	// 或晚于截止，普通设备上报也不受这项限制，这些时间不能代替操作结果时间参与
741	// 判断。截止前已接受的结果后来重复提交时不改写首次记录，这里使用的是首次接受
742	// 的时刻，不按重复提交时间判断。命中任意一条都必须返回 ErrCorruptStorage，
743	// 不能通过删除迟到结果、调整时间或把设备改成超时来继续打开。
744	func checkCampaignResultDeadline(campaignID string, c *campaignState) error {
745		for _, cd := range c.Devices {
746			ops := []struct {
747				stage string
748				op    *opState
749			}{
750				{StageDownload, &cd.Download},
751				{StageInstall, &cd.Install},
752				{StageRollback, &cd.Rollback},
753			}
754			for _, item := range ops {
755				o := item.op
756				// 未接受结果（含已领取未完成、随后超时）的操作没有结果时间，
757				// 属正常缺省，跳过核对。
758				if !o.HasResult {
759					continue
760				}
761				// time.Time 的比较按绝对时刻进行：结果不早于截止（相等或更晚）
762				// 即属迟到，同一时刻的不同时区写法判断相同。
763				if !o.At.Before(c.Deadline) {
764					return fmt.Errorf("%w: campaign %s device %s %s result at %s not before deadline %s",
765						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
766						o.At.Format(time.RFC3339Nano), c.Deadline.Format(time.RFC3339Nano))
767				}
768			}
769		}
770		return nil
771	}
772	
773	// checkSuccessReport 核对一条已接受的安装/回滚成功记录保存的附带上报与
774	// 对应设备影子最近接受的上报之间的关系。序号必须是正整数且不大于设备最近
775	// 接受的序号：缺失、为零或大于设备记录都按损坏处理。两边序号相等时，这条
776	// 成功记录代表的就是设备最近一次上报，其版本、完整上报配置与首次接受结果时
777	// 保存的发生时间必须分别与影子保存的版本、上报配置和最近上报时间一致
778	// （配置按 JSON 语义比较，时间按同一时刻判断，不因时区表示不同而报错）。
779	// 序号更小则是已被后续上报覆盖的历史记录，不要求与当前影子一致。
780	// 设备当前是否在线不影响本核对；下载结果、失败结果与没有成功结果的阶段
781	// 不保存附带上报序号，也不进入本核对。
782	func checkSuccessReport(campaignID string, dd diskDev, o diskOp, stage string, d *deviceState) error {
783		bad := func(format string, args ...any) error {
784			msg := fmt.Sprintf(format, args...)
785			return fmt.Errorf("%w: campaign %s device %s %s success report %s",
786				ErrCorruptStorage, campaignID, dd.DeviceID, stage, msg)
787		}
788		if o.ResultSeq == 0 {
789			return bad("missing report sequence")
790		}
791		if o.ResultSeq > d.LastSeq {
792			return bad("sequence %d not accepted by device (last accepted %d)", o.ResultSeq, d.LastSeq)
793		}
794		if o.ResultSeq == d.LastSeq {
795			if o.ResultVersion != d.Version {
796				return bad("version %s does not match latest reported version %s", o.ResultVersion, d.Version)
797			}
798			if !rawEqual(o.ResultConfig, d.Reported) {
799				return bad("config does not match latest reported config")
800			}
801			if !o.At.Equal(d.LastReportTime) {
802				return bad("time %s does not match latest report time %s",
803					o.At.Format(time.RFC3339Nano), d.LastReportTime.Format(time.RFC3339Nano))
804			}
805		}
806		return nil
807	}
