842	// validateDownloadStageDisk 校验 pending（等待下载）与 downloading（下载中）两种
843	// 设备状态与本设备在本活动中保存的下载操作进度一致。两种状态都必须停留在下载
844	// 阶段：pending 表示本设备在本活动中的下载从未领取、尚无下载结果；downloading
845	// 表示下载已经领取、但尚未接受任何下载结果。即使操作标识、时间与结果历史各自
846	// 合法，下载已领取却仍为等待下载、下载未领取却标为下载中，或已经保存下载成功
847	// 或失败结果却仍使用任一状态，都与事实矛盾；阶段已写成安装或回滚同样矛盾。
848	// 核对只看本设备在本活动中的下载操作记录：同批其他设备已领取或下载成功不能替
849	// 它补足进度，设备当前版本恰好等于目标版本、普通上报改变了版本或配置也不能
850	// 代替下载领取与结果。尚未领取下载时没有领取时间、尚无下载结果时没有结果时间，
851	// 是正常缺省；设备后来离线、维护窗口已结束都不使已保存的下载进度失效。矛盾
852	// 一律返回 ErrCorruptStorage，拒绝打开整个存储，不通过调整状态、撤销领取、
853	// 删除历史或补造下载结果消除矛盾。
854	func validateDownloadStageDisk(campaignID string, dd diskDev) error {
855		bad := func(msg string) error {
856			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
857		}
858		switch dd.Status {
859		case DevicePending, DeviceDownloading:
860		default:
861			return nil
862		}
863		if dd.Phase != StageDownload {
864			return bad("download-stage status without download phase")
865		}
866		switch dd.Status {
867		case DevicePending:
868			// 等待下载：下载从未领取、尚无下载结果；没有领取时间与结果时间是正常
869			// 缺省。下载已领取或已有成功/失败结果都与 pending 矛盾。
870			if dd.Download.Claimed || dd.Download.HasResult {
871				return bad("pending state with download claimed or resulted")
872			}
873		case DeviceDownloading:
874			// 下载中：下载已经领取，但还没有接受下载结果（成功或失败都不行）。
875			if !dd.Download.Claimed {
876				return bad("downloading state without download claim")
877			}
878			if dd.Download.HasResult {
879				return bad("downloading state with download result")
880			}
881		}
882		return nil
883	}
884	
885	// validateInstallStageDisk 校验 ready（等待安装）与 installing（正在安装）两种
886	// 设备状态与本设备在本活动中保存的操作进度一致。两种状态都必须已有本设备接受
887	// 的下载成功结果并停留在安装阶段：ready 表示安装从未领取、尚无安装结果；
888	// installing 表示安装已经领取、但还没有接受安装结果。即使操作标识、时间与结果
889	// 历史各自合法，已完成安装（安装成功或失败已有结果）的设备也不能解释成仍在
890	// 等待或正在安装，安装已经领取的记录同样不能停在 ready。核对只看本设备本活动
891	// 的下载/安装操作记录：不能借用同批其他设备的下载成功，也不能用设备当前版本
892	// 恰好等于目标版本替代下载或安装结果。尚未领取安装时没有安装领取时间、尚无
893	// 安装结果时没有结果时间，是正常缺省；设备离线、维护窗口已结束或普通上报改变
894	// 了当前版本都不在此核对范围内。矛盾一律返回 ErrCorruptStorage，拒绝打开整个
895	// 存储，不通过调整状态、撤销领取、删除历史或补造结果消除矛盾。
896	func validateInstallStageDisk(campaignID string, dd diskDev) error {
897		bad := func(msg string) error {
898			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
899		}
900		switch dd.Status {
901		case DeviceReady, DeviceInstalling:
902		default:
903			return nil
904		}
905		if dd.Phase != StageInstall {
906			return bad("install-stage status without install phase")
907		}
908		// 两种状态都必须有本设备在本活动中已接受的下载成功结果。
909		if !(dd.Download.HasResult && dd.Download.Success) {
910			return bad("install-stage status without accepted download success")
911		}
912		switch dd.Status {
913		case DeviceReady:
914			// 等待安装：安装从未领取、尚无安装结果；没有安装领取时间与结果时间
915			// 是正常缺省。安装已领取或已有成功/失败结果都与 ready 矛盾。
916			if dd.Install.Claimed || dd.Install.HasResult {
917				return bad("ready state with install claimed or resulted")
918			}
919		case DeviceInstalling:
920			// 正在安装：安装已经领取，但还没有接受安装结果（成功或失败都不行）。
921			if !dd.Install.Claimed {
922				return bad("installing state without install claim")
923			}
924			if dd.Install.HasResult {
925				return bad("installing state with install result")
926			}
927		}
928		return nil
929	}
930	
931	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
932	func validateRollbackDisk(campaignID string, dd diskDev) error {
933		bad := func(msg string) error {
934			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
935		}
936		rb := dd.Rollback
937		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
938		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
939		if dd.RollbackTarget != "" && !dd.Download.Claimed {
940			return bad("rollback target locked before download claim")
941		}
942		// 已领取下载且尚无下载结果，或已有成功下载结果：回滚目标必须已锁定，
943		// 字段缺失与空串按同一种损坏处理。这项要求不因设备进入安装阶段或
944		// 活动已结束而取消——否则安装失败后会留下没有明确恢复版本的回滚待办。
945		// 不能用当前影子版本、活动目标版本或允许升级列表替代丢失的目标。
946		// 首次领取前复查版本不兼容、直接在下载阶段失败的设备（下载已有失败
947		// 结果）允许没有目标：这种失败不进入安装或回滚。
948		if dd.RollbackTarget == "" && dd.Download.Claimed &&
949			(!dd.Download.HasResult || dd.Download.Success) {
950			return bad("missing locked rollback target")
951		}
952		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
953		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
954			return bad("rollback status without locked target")
955		}
956		// 回滚流程的唯一入口是“已接受本次安装的失败结果”：等待回滚、正在回滚
957		// 以及回滚成功/失败/超时的设备，都必须能从本设备在本活动中已经接受的
958		// 安装结果确认安装失败。安装尚未领取、已领取但没有结果，或安装结果为
959		// 成功，都不能支持任何回滚状态；即使回滚目标非空、操作标识合法、回滚
960		// 结果与历史一致或活动已结束，也必须核对这一前提。当前版本恰好等于旧
961		// 版本、下载失败以及其他设备或其他活动的失败记录都不能代替本次安装失败
962		// （这里只看本设备本活动保存的安装操作结果本身）。
963		installFailed := dd.Install.HasResult && !dd.Install.Success
964		if isRollbackFlowStatus(dd.Status) && !installFailed {
965			return bad("rollback state without accepted install failure")
966		}
967		switch dd.Status {
968		case DeviceAwaitingRollback:
969			// 已接受安装失败、回滚尚未领取：回滚无结果。
970			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
971				return bad("awaiting rollback state mismatch")
972			}
973		case DeviceRollingBack:
974			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
975				return bad("rolling back state mismatch")
976			}
977		case DeviceRollbackSucceeded:
978			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
979				return bad("rollback succeeded without success result")
980			}
981			if rb.ResultVersion != dd.RollbackTarget {
982				return bad("rollback version mismatch")
983			}
984			if _, ok := decodeObject(rb.ResultConfig); !ok {
985				return bad("rollback config invalid")
986			}
987		case DeviceRollbackFailed:
988			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
989				return bad("rollback failed without failure result")
990			}
991		case DeviceRollbackTimeout:
992			if dd.Phase != StageRollback {
993				return bad("rollback timeout phase mismatch")
994			}
995			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
996			if rb.HasResult {
997				return bad("rollback timeout with result")
998			}
999		default:
1000			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
1001			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
1002			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
1003			if dd.Install.HasResult && !dd.Install.Success {
1004				return bad("install failure without rollback state")
1005			}
1006			if rb.Claimed || rb.HasResult {
1007				return bad("rollback progressed without install failure")
1008			}
1009		}
1010		return nil
1011	}
1012

