34			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
35			At: dlOK, Success: true,
36		}); err != nil {
37			t.Fatal(err)
38		}
39		in, _ := s.Claim(spec.ID, "d1", upBase.Add(4*time.Minute))
40		installFailAt := upBase.Add(5 * time.Minute)
41		installFail := OperationResult{
42			CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
43			At: installFailAt, Success: false, Reason: "install broken",
44		}
45		if err := s.SubmitResult(installFail); err != nil {
46			t.Fatalf("install failure: %v", err)
47		}
48	
49		cv, _ := s.GetCampaign(spec.ID)
50		rec, ok := findResultRecord(cv, in.ID)
51		if !ok {
52			t.Fatalf("install failure record missing: %+v", cv.Results)
53		}
54		if rec.DeviceID != "d1" || rec.Stage != StageInstall || rec.Success ||
55			rec.Reason != "install broken" || !rec.At.Equal(installFailAt) || rec.Version != "" {
56			t.Fatalf("install failure record: %+v", rec)
57		}
58		nAfterInstall := len(cv.Results)
59	
60		// 相同原因、更晚时间重复提交：成功且不增加历史、不重复触发回滚。
61		installFail.At = upBase.Add(40 * time.Minute)
62		if err := s.SubmitResult(installFail); err != nil {
63			t.Fatalf("replay install failure: %v", err)
64		}
65		if cv, _ = s.GetCampaign(spec.ID); len(cv.Results) != nAfterInstall {
66			t.Fatalf("replay install failure added history: %+v", cv.Results)
67		}
68		// 改用不同原因：冲突，原记录（原因与首次时间）不变。
69		installFail.At = upBase.Add(41 * time.Minute)
70		installFail.Reason = "install broken differently"
71		if err := s.SubmitResult(installFail); !errors.Is(err, ErrResultConflict) {
72			t.Fatalf("changed install reason conflict: %v", err)
73		}
74		cv, _ = s.GetCampaign(spec.ID)
75		if rec, _ = findResultRecord(cv, in.ID); rec.Reason != "install broken" || !rec.At.Equal(installFailAt) {
76			t.Fatalf("original install failure altered: %+v", rec)
77		}
78		if findDevice(cv, "d1").Status != DeviceAwaitingRollback {
79			t.Fatalf("conflict must not change state: %+v", findDevice(cv, "d1"))
80		}
81	
82		// 回滚失败：同一条统一规则下的另一条记录，保留自己的原因与时间。
83		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
84		rbFailAt := upBase.Add(9 * time.Minute)
85		if err := s.SubmitResult(OperationResult{
86			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
87			At: rbFailAt, Success: false, Reason: "rb boom",
88		}); err != nil {
89			t.Fatalf("rollback failure: %v", err)
90		}
91		// 活动已结束后，相同回滚失败原因以更晚时间重放：仍成功且不增加历史。
92		if err := s.SubmitResult(OperationResult{
93			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
94			At: upBase.Add(3 * time.Hour), Success: false, Reason: "rb boom",
95		}); err != nil {
96			t.Fatalf("replay rollback failure after end: %v", err)
97		}
98	
99		cv, _ = s.GetCampaign(spec.ID)
100		if !cv.Ended || cv.Status != CampaignFailed {
101			t.Fatalf("campaign ends rollback-failed: %+v", cv)
102		}
103		// 下载成功、安装失败、回滚失败各一条，共三条。
104		if len(cv.Results) != 3 {
105			t.Fatalf("history should hold exactly 3 records: %+v", cv.Results)
106		}
107		rbRec, ok := findResultRecord(cv, rb.ID)
108		if !ok {
109			t.Fatalf("rollback failure record missing: %+v", cv.Results)
110		}
111		if rbRec.DeviceID != "d1" || rbRec.Stage != StageRollback || rbRec.Success ||
112			rbRec.Reason != "rb boom" || !rbRec.At.Equal(rbFailAt) || rbRec.Version != "" {
113			t.Fatalf("rollback failure record: %+v", rbRec)
114		}
115		// 安装失败原记录仍在、内容不变。
116		inRec, _ := findResultRecord(cv, in.ID)
117		if inRec.Reason != "install broken" || !inRec.At.Equal(installFailAt) {
118			t.Fatalf("install failure record changed after rollback: %+v", inRec)
119		}
120	}
121	
122	// 未开启回滚时的下载失败（含首次领取时版本不兼容的自动失败）同样遵循统一
123	// 记录规则：一条对应下载操作的失败历史，记录原因与首次接受时间，可重放、
124	// 不因换原因被覆盖，且不产生任何回滚记录。
125	func TestDownloadFailureFollowsUnifiedRecordRule(t *testing.T) {
126		check := func(t *testing.T, cv CampaignView, dlID, wantReason string, failAt time.Time) {
127			t.Helper()
128			rec, ok := findResultRecord(cv, dlID)
129			if !ok {
