131			}
132			if rec.DeviceID != "d1" || rec.Stage != StageDownload || rec.Success ||
133				rec.Reason != wantReason || !rec.At.Equal(failAt) || rec.Version != "" {
134				t.Fatalf("download failure record: %+v", rec)
135			}
136			if len(cv.Results) != 1 {
137				t.Fatalf("download failure adds exactly one record: %+v", cv.Results)
138			}
139			if d := findDevice(cv, "d1"); d.Status != DeviceFailed || d.Phase != StageDownload ||
140				d.RollbackResult || d.RollbackTarget != "" {
141				t.Fatalf("download failure must not rollback: %+v", d)
142			}
143		}
144	
145		// 普通下载失败。
146		s := setupUpgrade(t, "d1")
147		spec := upSpec()
148		spec.Devices = []string{"d1"}
149		spec.BatchSize = 1
150		createCampaign(t, s, spec)
151		bringOnline(t, s, "d1")
152		dl, _ := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
153		failAt := upBase.Add(3 * time.Minute)
154		if err := s.SubmitResult(OperationResult{
155			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
156			At: failAt, Success: false, Reason: "dl down",
157		}); err != nil {
158			t.Fatal(err)
159		}
160		// 活动结束后相同原因、变化时间重放：保留原历史。
161		if err := s.SubmitResult(OperationResult{
162			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
163			At: upBase.Add(3 * time.Hour), Success: false, Reason: "dl down",
164		}); err != nil {
165			t.Fatalf("replay download failure after end: %v", err)
166		}
167		// 不同原因仍冲突。
168		if err := s.SubmitResult(OperationResult{
169			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
170			At: upBase.Add(3*time.Hour + time.Minute), Success: false, Reason: "other",
171		}); !errors.Is(err, ErrResultConflict) {
172			t.Fatalf("changed download reason conflict: %v", err)
173		}
174		cv, _ := s.GetCampaign(spec.ID)
175		check(t, cv, dl.ID, "dl down", failAt)
176	
177		// 首次领取下载时版本不兼容：领取即接受下载失败，走同一条记录规则。
178		s2 := setupUpgrade(t, "d1")
179		spec2 := upSpec()
180		spec2.Devices = []string{"d1"}
181		spec2.BatchSize = 1
182		createCampaign(t, s2, spec2)
183		bringOnline(t, s2, "d1")
184		if err := s2.Report("d1", 2, upBase.Add(time.Minute), "v9", json.RawMessage(`{}`)); err != nil {
185			t.Fatal(err)
186		}
187		incompatAt := upBase.Add(2 * time.Minute)
188		if _, err := s2.Claim(spec2.ID, "d1", incompatAt); !errors.Is(err, ErrIncompatibleVersion) {
189			t.Fatalf("incompatible claim: %v", err)
190		}
191		cv2, _ := s2.GetCampaign(spec2.ID)
192		dlID2 := findDevice(cv2, "d1").DownloadID
193		wantReason := "version v9 is not compatible with target v2"
194		check(t, cv2, dlID2, wantReason, incompatAt)
195	}
